function persist(){
 clearTimeout(saveTimer);ui.pendingDraft=false;
 if(!save())toast('Your appearance preference could not be saved.');
 if(!sync||!canWriteWorkspace(state,connectionStatus))return Promise.resolve(true);
 return sync.save(state).then(()=>true,()=>false);
}
function schedulePersist(){clearTimeout(saveTimer);ui.pendingDraft=true;syncStatus('saving');saveTimer=setTimeout(()=>void persist(),650)}
function syncStatus(status,error){
 ui.saveState=status;if(error)ui.saveError=publicError(error);else if(status!=='error')ui.saveError='';
 const messages={saving:'Saving…',saved:'Saved to workspace',error:'Unsaved changes'};
 document.querySelectorAll('[data-save-state],#save-status,#intake-save-label').forEach(node=>node.textContent=messages[status]);
 const banner=document.querySelector('#workspace-save-error');
 if(banner){banner.hidden=status!=='error';banner.querySelector('p').textContent=ui.saveError}
 if(error)toast(ui.saveError);
}
window.addEventListener('beforeunload',event=>{if(sync?.dirty||ui.pendingDraft){event.preventDefault();event.returnValue=''}});
function requireWorkspace(){if(canWriteWorkspace(state,connectionStatus)&&!ui.readOnlyPreview)return true;toast(state.session?'Your account is signed in. Finish the workspace database connection before adding or saving records.':'Sign in before adding or saving records.');return false;}
function renderBase(){if((ui.authChecking||ui.workspaceLoading)&&!ui.readOnlyPreview){app.innerHTML=views.accountLoading(ui.workspaceLoading?'Opening your workspace…':'Checking your session…',Boolean(state.session));return}if(!state.session&&!ui.readOnlyPreview){app.innerHTML=views.login(ui.authError);return}if(state.session&&!state.verified&&!ui.readOnlyPreview){app.innerHTML=views.accountConnection(ui.workspaceError);return}if(!state.onboarded&&!ui.readOnlyPreview){app.innerHTML=views.setup();return}let requested=location.hash.slice(1).split('?')[0]||'dashboard';if(requested==='generation-history')requested='analysis';ui.route=views.navigation.some(n=>n[0]===requested)||requested==='report-editor'?requested:'dashboard';if(ui.route==='report-editor'&&!ui.planId)ui.planId=sessionStorage.getItem('dia-selected-plan')||state.plans.at(-1)?.id;const content={dashboard:()=>views.dashboard(),clients:()=>views.clients(ui),'diet-plans':()=>views.planList(ui),create:()=>views.create(ui),'report-editor':()=>views.editor(ui),progress:()=>views.progress(ui),subscriptions:()=>views.subscriptions(),billing:()=>views.billing(),analysis:()=>analysis(ui),notifications:()=>views.notifications(),settings:()=>views.settings()}[ui.route]();app.innerHTML=views.shell(ui.route,content)}
function applyTheme(){document.documentElement.dataset.theme=state.theme||'light';document.querySelector('meta[name=theme-color]')?.setAttribute('content',state.theme==='dark'?'#212121':'#eceae3')}
function syncThemeControls(){const next=state.theme==='dark'?'light':'dark';document.querySelectorAll('[data-action="toggle-theme"]').forEach(button=>{if(button.classList.contains('theme-toggle')){button.setAttribute('aria-label','Switch to '+next+' theme');button.innerHTML='<span class="theme-symbol"></span><span>'+(next==='light'?'Light':'Dark')+'</span>'}else button.textContent='Use '+next+' theme'})}
function updatePrint(p){let sheet=document.querySelector('#report-print-settings');if(!sheet){sheet=document.createElement('style');sheet.id='report-print-settings';document.head.append(sheet)}const size=['A4','Letter','Legal'].includes(p?.style.pageSize)?p.style.pageSize:'A4';const orientation=p?.style.orientation==='Landscape'?'landscape':'portrait';const margin=Math.max(5,Math.min(35,Number(p?.style.margin||15)));sheet.textContent='@media print{@page{size:'+size+' '+orientation+';margin:0mm}}'}
function render(){clearTimeout(pageTimer);applyTheme();closeDropdowns();renderBase();if(!ui.readOnlyPreview&&(!state.session||!state.onboarded))app.insertAdjacentHTML('beforeend','<button class="theme-toggle auth-theme-switch" data-action="toggle-theme" aria-label="Switch to '+(state.theme==='dark'?'light':'dark')+' theme"><span class="theme-symbol"></span>'+(state.theme==='dark'?'Light':'Dark')+'</button>');enhanceSelects(app);if(ui.saveState)syncStatus(ui.saveState);if(ui.readOnlyPreview){app.querySelectorAll('form:not(#global-search) input,form:not(#global-search) textarea,form:not(#global-search) select,form:not(#global-search) button').forEach(control=>control.disabled=true)}if(ui.route==='report-editor'&&getPlan(ui.planId)){updatePrint(getPlan(ui.planId));paginateDocument(getPlan(ui.planId))}}
function go(route){closeModal();if(location.hash==='#'+route)render();else location.hash=route}
function showModal(title,content,name='',wide=false){previousFocus=document.activeElement;modalName=name;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-heading"><h2 id="modal-title">${title}</h2>${button('×','close-modal','icon-button','aria-label="Close dialog"')}</div>${content}</section></div>`;document.body.classList.add('modal-open');enhanceSelects(overlay);overlay.querySelector('input,button,select')?.focus()}
function closeModal(){overlay.innerHTML='';document.body.classList.remove('modal-open');modalName='';previousFocus?.focus?.();if(document.querySelector('.job-view'))refreshJob()}
function confirmation(title,text,action,attrs=''){showModal(title,`<p>${text}</p><div class="form-footer">${button('Cancel','close-modal','secondary')}${button('Confirm','confirm-'+action,'primary',attrs)}</div>`)}
function onboardingPrompt(){showModal('Complete your profile',`<div class="welcome-fruit">${fruit('apple')}</div><p>Before you enter your workspace, complete your general profile, company details, and professional credibility.</p><div class="notice">All steps are required. Progress is saved as you go. </div>${button('Let’s get started →','close-modal','primary wide')}`,'onboarding')}
const tourSteps=[['Welcome to DIA','This is your practice overview: clients, drafts, published plans, and your available credits.','dashboard'],['Every client has a home','Find client details, diet plans, check-ins, and practitioner notes together.','clients'],['Create with context','Select a client, review their details, and set the plan requirements. Generation stages stay visible.','create'],['Your report, your style','Open a plan to edit meals, colours, type, notes, and your logo. Export a PDF or editable document.','diet-plans'],['Keep the journey visible','Record check-ins and follow weight, adherence, and energy over time.','progress'],['Room to grow','Manage Standard, Pro, or Plus and buy additional credits without upgrading.','subscriptions']];
function showTour(){const [title,text,route]=tourSteps[tourIndex];if(location.hash!=='#'+route){location.hash=route;render()}showModal(title,`<div class="tour-count">WORKSPACE TOUR · ${tourIndex+1} / ${tourSteps.length}</div><p>${text}</p><div class="tour-dots">${tourSteps.map((_,i)=>`<i class="${i===tourIndex?'active':''}"></i>`).join('')}</div><div class="form-footer">${button('Skip tour','skip-tour','text-btn')}<div>${tourIndex?button('Back','tour-back','secondary'):''}${button(tourIndex===tourSteps.length-1?'Finish tour':'Next →','tour-next')}</div></div>`,'tour')}
function refreshJob(){
 if(!state.session||!state.onboarded||overlay.innerHTML)return;
 if(ui.route==='create'){
  const view=document.querySelector('.job-view');
  const job=state.jobs.find(j=>j.id===view?.dataset.job);
  if(view&&job){const action=view.contains(document.activeElement)?document.activeElement.dataset.action:null;const focusedDisclosure=document.activeElement?.closest('[data-disclosure]')?.dataset.disclosure;const disclosure=ui.generationDisclosures?.[job.id]||{};view.outerHTML=views.jobView(job);for(const [key,open] of Object.entries(disclosure)){const details=document.querySelector(`.job-view [data-disclosure="${key}"]`);if(details)details.open=open}if(action)document.querySelector(`.job-view [data-action="${action}"]`)?.focus({preventScroll:true});else if(focusedDisclosure)document.querySelector(`.job-view [data-disclosure="${focusedDisclosure}"] summary`)?.focus({preventScroll:true})}
  return;
 }
 if(['analysis','dashboard'].includes(ui.route)&&!document.activeElement?.matches('input,textarea,[role="combobox"]'))render();
}
function captureIntake(){const form=document.querySelector('#intake-form,#requirements-form');if(!form)return intakeContext(ui).answers;const client=getClient(form.dataset.clientId);if(!client)return {};const saved=state.intakeDrafts[client.id]||{};const answers={...clientIntake(client),...saved.answers,...ui.createDraft};const values=Object.fromEntries(new FormData(form));delete values.clientId;for(const key of ['privacyConsent','review','updateClient']){if(form.querySelector(`[name="${key}"]`))values[key]=form.querySelector(`[name="${key}"]`).checked}Object.assign(answers,values);if(answers.privacyConsent&&!answers.consentRecordedAt)answers.consentRecordedAt=new Date().toISOString();if(!answers.privacyConsent)delete answers.consentRecordedAt;ui.createClientId=client.id;ui.createDraft=answers;state.lastIntakeClientId=client.id;state.intakeDrafts[client.id]={...saved,answers:structuredClone(answers),step:Number(form.dataset.step),updatedAt:Date.now()};schedulePersist();return answers}
function saveIntakeStep(step){const c=intakeContext(ui).client;ui.createStep=step;if(c){const record=state.intakeDrafts[c.id]||{answers:structuredClone(intakeContext(ui).answers)};record.step=step;record.updatedAt=Date.now();state.intakeDrafts[c.id]=record;state.lastIntakeClientId=c.id;persist()}}
function updateIntakeProgress(){const answers=intakeContext(ui).answers;const progress=completion(answers);const label=document.querySelector('#intake-completion');if(label)label.innerHTML=progress.percent+'<small>%</small>';const count=document.querySelector('#intake-count');if(count)count.textContent=progress.done+' of '+progress.total+' required answers';const fill=document.querySelector('#intake-progress-fill');if(fill)fill.style.width=progress.percent+'%';document.querySelectorAll('[data-section-status]').forEach(el=>{const i=Number(el.dataset.sectionStatus);const done=Object.keys(validateIntake(answers,i,false)).length===0;el.classList.toggle('complete',done);el.textContent=done?'✓':String(i+1).padStart(2,'0')});document.querySelectorAll('[data-mobile-completion]').forEach(el=>el.textContent=progress.percent+'% · '+progress.done+' of '+progress.total+' required answers');document.querySelectorAll('[data-mobile-progress]').forEach(el=>el.style.width=progress.percent+'%');const saveLabel=document.querySelector('#intake-save-label');if(saveLabel)saveLabel.textContent=ui.saveState==='error'?'Unsaved changes':ui.saveState==='saved'?'Saved to workspace':'Saving…'}
function openIntake(clientId){if(clientId&&getClient(clientId)?.status==='Archived'){toast('Reactivate this archived client before creating a plan.');return}ui.clientGroup=null;if(clientId)ui.createClientId=clientId;ui.createDraft={};ui.createStep=undefined;ui.currentJob=undefined;ui.intakeErrors={};ui.generationError='';const {client,saved}=intakeContext(ui);if(saved?.step===5){const job=state.jobs.find(j=>j.id===saved.jobId);if(job?.status==='Running'){ui.currentJob=job.id;ui.createStep=5}else{saved.step=0;delete saved.jobId;saved.answers={...saved.answers,...clientIntake(client),model:state.tier};delete saved.answers.revisionOf;delete saved.answers.revisionReason;saved.answers.privacyConsent=false;saved.answers.review=false;delete saved.answers.consentRecordedAt;persist()}}if(client)state.lastIntakeClientId=client.id;go('create')}
async function startJob(input,clientId){
 if(!requireWorkspace())return;
 const errors=validateGenerationRequest(input);
 if(Object.keys(errors).length||input.review!==true){toast('Complete and review the client assessment first.');return}
 try {await services.generation.start({clientId,input,requestId:uid('REQUEST')});}
 catch(error){toast(publicError(error));}
}
