function receiveAccount(account,error='') {
 const epoch=++accountEpoch;currentAccount=account;sync?.stop();sync=null;
 clearTimeout(pageTimer);clearTimeout(saveTimer);certificateRead=undefined;tableTarget=undefined;searchIndex=-1;tourIndex=0;
 closeModal();applyAccountSession(state,account);
 for(const key of Object.keys(ui))delete ui[key];
 Object.assign(ui,{route:'dashboard',clientTab:'Overview',createDraft:{},editorTab:'Design',authChecking:false,authError:error});
 try{sessionStorage.removeItem('dia-selected-plan')}catch{}
 document.querySelector('#toasts').replaceChildren();render();
 if(account)void loadAccountWorkspace(account,epoch);
}
async function loadAccountWorkspace(account,epoch){
 ui.workspaceLoading=true;ui.workspaceError='';render();
 try{
  const repository=await (repositoryPromise ||= initializeFirestoreWorkspace());
  if(epoch!==accountEpoch)return;
  const loaded=await repository.loadWorkspace(account);
  if(epoch!==accountEpoch)return;
  const theme=state.theme;
  Object.assign(state,loaded,{theme,session:true,userId:account.uid,emailVerified:account.emailVerified,verified:true});
  state.profile.email ||= account.email;state.profile.name ||= account.displayName;
  connectServices({auth:authService,repository});
  sync=createWorkspaceSync(snapshot=>repository.saveWorkspace(snapshot),(status,error)=>{if(epoch===accountEpoch)syncStatus(status,error)});
  ui.workspaceLoading=false;ui.readOnlyPreview=false;render();
  if(!state.onboarded)onboardingPrompt();else if(!state.tourDone){tourIndex=0;showTour()}
 }catch(error){if(epoch!==accountEpoch)return;ui.workspaceLoading=false;ui.workspaceError=error.code==='permission-denied'?'Your account is signed in, but the private workspace rules have not been activated in Firestore yet.':publicError(error);render()}
}
async function signOutAccount(button) {
 if(!state.session){ui.readOnlyPreview=false;closeModal();render();return}
 button.disabled=true;
 try{await services.auth.signOut();receiveAccount(null)}
 catch(error){button.disabled=false;toast(publicError(error))}
}
async function connectAccount() {
 try{
  authService=await initializeFirebaseAuthentication();
  connectServices({auth:authService});
  authService.observeSession(account=>receiveAccount(account),error=>receiveAccount(null,publicError(error)));
 }catch(error){receiveAccount(null,publicError(error))}
}
render();
void connectAccount();

function updateGlobalSearch(input){const menu=document.querySelector('#global-search-results');if(!menu)return;menu.innerHTML=searchResults(input.value);menu.hidden=false;input.setAttribute('aria-expanded','true');input.removeAttribute('aria-activedescendant');searchIndex=-1}
function hideGlobalSearch(){const menu=document.querySelector('#global-search-results');if(menu)menu.hidden=true;const input=document.querySelector('#global-search-input');input?.setAttribute('aria-expanded','false');input?.removeAttribute('aria-activedescendant');searchIndex=-1}
document.addEventListener('focusin',e=>{if(e.target.id==='global-search-input')updateGlobalSearch(e.target)});
document.addEventListener('click',e=>{if(!e.target.closest('#global-search'))hideGlobalSearch()});
document.addEventListener('keydown',e=>{if(e.target.id!=='global-search-input')return;const options=[...document.querySelectorAll('.global-search-result')];if(e.key==='Escape'){hideGlobalSearch();return}if(e.key==='Enter'&&searchIndex>=0){e.preventDefault();options[searchIndex]?.click();return}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(!options.length)return;searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((option,i)=>option.setAttribute('aria-selected',String(i===searchIndex)));e.target.setAttribute('aria-activedescendant',options[searchIndex].id)}});
document.addEventListener('selectionchange',()=>{rememberDocumentSelection();const node=window.getSelection()?.anchorNode;selectTableFromNode(node?.nodeType===1?node:node?.parentElement)});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action="doc-command"],[data-action="doc-link"],[data-action="doc-table"],[data-action="doc-page-break"],[data-action="doc-table-row"],[data-action="doc-table-column"],[data-action="doc-table-properties"],[data-action^="doc-delete"],[data-action="doc-merge-cell"],[data-action="doc-split-cell"]'))e.preventDefault()});
document.addEventListener('paste',e=>{if(!e.target.closest('[data-document]'))return;if(!requireWorkspace()){e.preventDefault();return}e.preventDefault();ensureRevision(getPlan(ui.planId));const html=e.clipboardData.getData('text/html');if(html)applyDocumentCommand('insertHTML',cleanRichText(html));else applyDocumentCommand('insertText',e.clipboardData.getData('text/plain'));saveCurrentDocument()});
async function readCertification(input){if(!connectionStatus.files){input.value='';toast('Secure file uploads are the next connection step. Profile details entered so far remain saved.');return}const file=input.files?.[0];if(!file)return;const target=state.onboarded?state.profile:state.setup;if(!['application/pdf','image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PDF, PNG or JPG under 2 MB.');input.value='';return}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const old=target.certification;target.certification={name:file.name,type:file.type,size:file.size,data,uploadedAt:new Date().toISOString()};if(!save()){target.certification=old;input.value='';toast('Browser storage is full. Choose a smaller certificate.');return}document.querySelector('#certification-current').innerHTML=certificateSummary(target.certification);input.required=false;toast('Certification uploaded locally.')}
function syncCustomLogo(plan){if(!plan.documentHtml)return;const doc=new DOMParser().parseFromString(plan.documentHtml,'text/html');const logo=doc.querySelector('.report-logo');if(logo){logo.style.textAlign=plan.style.logoAlign||'left';const img=logo.querySelector('img');if(img){img.src=plan.style.logo||logoUrl;img.style.maxWidth=(plan.style.logoWidth||150)+'px'}}plan.documentHtml=cleanRichText(doc.body.innerHTML)}
